type pt = [2]float64

// bodyRig is one body sprite's attachments.
type bodyRig struct{ head, hold, back pt }

// fakeBodies are the test body attachments per drawn facing (values as
// generated by the limbless rig: hold right-front, back between the
// shoulders; north holds on the far side).
var fakeBodies = map[art.Facing]bodyRig{
	art.FaceSouth: {head: pt{80, 122}, hold: pt{98.5, 188.8}, back: pt{80, 159.6}},
	art.FaceEast:  {head: pt{82.4, 121.5}, hold: pt{100, 186.5}, back: pt{65.9, 161.9}},
	art.FaceNorth: {head: pt{80, 121.1}, hold: pt{61.5, 182.6}, back: pt{80, 164.2}},
}

func fakeSprite(canvas [2]int, origin pt, attach map[string]pt) *art.Sprite {
	return &art.Sprite{
		Meta: art.Meta{Canvas: canvas, Origin: origin, Attach: attach},
		Pix:  image.NewNRGBA(image.Rect(0, 0, canvas[0]/8, canvas[1]/8)),
	}
}

// staleHandKey is the hand dot sprite the renderer no longer draws:
// fakeCombatArt still carries one so tests can assert it never appears.
const staleHandKey = "pawn/hand"

// fakeCombatArt is a catalog with rigged bodies (south, east, north), a
// stale hand dot and the gear attachments (values as generated by the
// gear family).
func fakeCombatArt() *art.Catalog {
	c := &art.Catalog{Sprites: map[string]*art.Sprite{}, Tinted: map[art.TintKey]*ebiten.Image{}}
	for f, b := range fakeBodies {
		c.Sprites["pawn/body_"+f.String()] = fakeSprite([2]int{160, 297}, pt{16, 153},
			map[string]pt{"head": b.head, "hold": b.hold, "back": b.back})
	}
	c.Sprites[staleHandKey] = fakeSprite([2]int{128, 136}, pt{0, 8}, map[string]pt{"center": {64, 69.6}})
	gear := [2]int{160, 168}
	o := pt{16, 24}
	c.Sprites["weapon/rifle_basic"] = fakeSprite(gear, o, map[string]pt{"grip": {63.4, 84.8}, "support": {97.9, 85.1}, "muzzle": {136.3, 85.8}, "stock": {28.8, 85.4}})
	c.Sprites["weapon/spear"] = fakeSprite(gear, o, map[string]pt{"grip": {37.8, 83.4}, "support": {69.8, 83.4}, "tip": {146.6, 84.1}})
	c.Sprites["weapon/knife"] = fakeSprite(gear, o, map[string]pt{"grip": {54.4, 82.4}, "support": {71, 82.4}, "tip": {126.1, 83.1}})
	c.Sprites["weapon/club"] = fakeSprite(gear, o, map[string]pt{"grip": {51.8, 85.4}, "support": {69.8, 85.4}, "tip": {136.3, 84.2}})
	c.Sprites["item/wood_pile"] = fakeSprite([2]int{160, 173}, pt{16, 29}, map[string]pt{})
	return c
}

func artRenderer() *Renderer {
	r := New(&stubSim{w: 64, h: 64, tick: 100})
	r.art = fakeCombatArt()
	return r
}

// rigFor is a default pawn's rig facing f, and its standing pose (mirrored
// facing west, as drawPawnFigure draws it).
func rigFor(r *Renderer, f art.Facing) (creature.HeldRig, motionpkg.Pose) {
	rig := r.rigOf(game.PawnView{}, f)
	ps := creature.StandPose()
	if rig.Mirror {
		ps = creature.Mirrored(ps)
	}
	return rig, ps
}

// bodyPoint is a body attachment on screen for a figure at (wx, wy) in
// pose ps.
func bodyPoint(r *Renderer, rig creature.HeldRig, ps motionpkg.Pose, name string, wx, wy, tile float64) pt {
	sx, sy := r.worldToScreenF(wx, wy)
	bx, by, s := art.Origin(rig.Body.Meta, float64(sx), float64(sy), tile)
	a := rig.Body.Meta.Attach[name]
	g := ps.Geo(float64(sx), float64(sy), tile)
	return apply(g, pt{bx + a[0]*s, by + a[1]*s})
}

func apply(g ebiten.GeoM, p pt) pt {
	x, y := g.Apply(p[0], p[1])
	return pt{x, y}
}

func near2(a, b pt, tol float64) bool { return math.Hypot(a[0]-b[0], a[1]-b[1]) <= tol }

// heldPivotOn is a placed held item's pivot on screen.
func heldPivotOn(r *Renderer, pl creature.HeldPlacement, h creature.HeldItem) pt {
	return apply(pl.G, creature.HeldPivot(r.art.Sprite(h.Key), h.Stance))
}

// bodyBox is the body's torso on screen (pre-pose canvas: the head's x
// +-28 px, from the head down to the feet), as min/max corners.
func bodyBox(r *Renderer, rig creature.HeldRig, ps motionpkg.Pose, wx, wy, tile float64) (lo, hi pt) {
	m := rig.Body.Meta
	head := m.Attach["head"]
	feet := m.Origin[1] + creature.PawnFeetY*art.TilePx
	sx, sy := r.worldToScreenF(wx, wy)
	bx, by, s := art.Origin(m, float64(sx), float64(sy), tile)
	g := ps.Geo(float64(sx), float64(sy), tile)
	a := apply(g, pt{bx + (head[0]-28)*s, by + head[1]*s})
	b := apply(g, pt{bx + (head[0]+28)*s, by + feet*s})
	return pt{math.Min(a[0], b[0]), math.Min(a[1], b[1])}, pt{math.Max(a[0], b[0]), math.Max(a[1], b[1])}
}

func inBox(p, lo, hi pt) bool {
	return p[0] >= lo[0] && p[0] <= hi[0] && p[1] >= lo[1] && p[1] <= hi[1]
}

// Off duty nothing is held: no weapon, slung or in hand, whatever the
// pawn does (idle, walking, working, eating); on duty the weapon is
// carried.
func TestNoWeaponWhenOffDuty(t *testing.T) {
	t.Parallel()
	r := artRenderer()
	walking := motionpkg.MoveState{Blend: 1, Moving: true, Speed: 0.06}
	for _, w := range []string{"rifle", "knife", "spear", "club", "fists"} {
		for _, m := range []motionpkg.MoveState{{}, walking} {
			if h := r.creatures().IdleHeld(game.PawnView{Weapon: w}, m); h.Key != "" {
				t.Fatalf("%s off duty: nothing held: %+v", w, h)
			}
		}
		for _, act := range []string{game.ActionChop, game.ActionEat, game.ActionSow, game.ActionCraft, ""} {
			p := game.PawnView{ID: 3, X: 5, Y: 5, ActX: 6, ActY: 5, Weapon: w, Action: act}
			if _, h := r.standingPose(p, motionpkg.MoveState{}); h.Key != "" {
				t.Fatalf("%s off duty, %q: nothing held: %+v", w, act, h)
			}
		}
	}
	for _, q := range []game.PawnView{
		{Weapon: "rifle", Drafted: true},
		{Weapon: "rifle", Action: game.ActionAim},
		{Weapon: "spear", Hostile: true},
		{Weapon: "knife", Action: game.ActionMelee},
	} {
		want, _ := creature.HeldWeaponKey(q.Weapon)
		if h := r.creatures().IdleHeld(q, motionpkg.MoveState{}); h.Key != want || h.Stance != creature.StanceCarried {
			t.Fatalf("on duty (%+v) the weapon is carried: %+v", q, h)
		}
	}
	if h := r.creatures().IdleHeld(game.PawnView{Weapon: "rifle", Hostile: true, Fleeing: true}, motionpkg.MoveState{}); h.Key != "" {
		t.Fatal("a fleeing raider holds nothing")
	}
	if h := r.creatures().IdleHeld(game.PawnView{Weapon: "fists", Drafted: true}, motionpkg.MoveState{}); h.Key != "" {
		t.Fatal("fists: nothing held")
	}
	// the figure draw: body layers only
	r.art = figureArt()
	for f := art.FaceSouth; f <= art.FaceWest; f++ {
		for _, k := range drawnKeys(r, game.PawnView{ID: 1, X: 2, Y: 2, Weapon: "rifle"}, f) {
			if !strings.HasPrefix(k, "pawn/") || k == staleHandKey {
				t.Fatalf("%v off duty draws %s", f, k)
			}
		}
	}
}

// On duty at rest the weapon is carried low across the body: its centre
// on the torso, below the body centre, at a downward diagonal; forward
// facing east (west mirrored).
func TestCarriedWeaponOverlapsBody(t *testing.T) {
	t.Parallel()
	r := artRenderer()
	const tile = 64.0
	for f := art.FaceSouth; f <= art.FaceWest; f++ {
		rig, ps := rigFor(r, f)
		lo, hi := bodyBox(r, rig, ps, 3, 4, tile)
		for _, key := range []string{"weapon/rifle_basic", "weapon/spear", "weapon/knife", "weapon/club"} {
			h := creature.HeldItem{Key: key, Stance: creature.StanceCarried}
			pl, ok := r.heldPlace(rig, h, 3, 4, tile, ps)
			if !ok {
				t.Fatalf("%v %s: no placement", f, key)
			}
			c := heldPivotOn(r, pl, h)
			if !inBox(c, lo, hi) {
				t.Fatalf("%v %s: centre %v off the body %v..%v", f, key, c, lo, hi)
			}
			if mid := (lo[1] + hi[1]) / 2; c[1] <= mid-4 {
				t.Fatalf("%v %s: carried low: centre %v above the torso's middle %v", f, key, c, mid)
			}
			sp := r.art.Sprite(key).Meta.Attach
			end := sp["muzzle"]
			if _, ok := sp["tip"]; ok {
				end = sp["tip"]
			}
			e := apply(pl.G, end)
			if e[1] <= c[1] {
				t.Fatalf("%v %s: the forward end points down: end %v centre %v", f, key, e, c)
			}
			if fwd := e[0] - c[0]; (f == art.FaceWest) != (fwd < 0) {
				t.Fatalf("%v %s: forward end on the wrong side: %v", f, key, fwd)
			}
			if mirrored := creature.Det(pl.G) < 0; mirrored != (f == art.FaceWest) {
				t.Fatalf("%v %s: mirrored=%v, want only west", f, key, mirrored)
			}
		}
	}
	// facing east the carried weapon sits forward of facing south's
	rs, pss := rigFor(r, art.FaceSouth)
	re, pse := rigFor(r, art.FaceEast)
	h := creature.HeldItem{Key: "weapon/rifle_basic", Stance: creature.StanceCarried}
	ps1, _ := r.heldPlace(rs, h, 3, 4, tile, pss)
	pe, _ := r.heldPlace(re, h, 3, 4, tile, pse)
	if dx := heldPivotOn(r, pe, h)[0] - heldPivotOn(r, ps1, h)[0]; dx < 0.1*tile {
		t.Fatalf("east: the weapon forward by about %.2f tile, got %.1f px", creature.CarriedAhead, dx)
	}
	// a body without a head point places nothing
	r.art.Sprites["pawn/body_east"] = fakeSprite([2]int{160, 297}, pt{16, 153}, map[string]pt{"hold": {82, 111}})
	rig, ps := rigFor(r, art.FaceEast)
	if _, ok := r.heldPlace(rig, h, 3, 4, tile, ps); ok {
		t.Fatal("no head attachment: no placement")
	}
}

func TestHeldDraws(t *testing.T) {
	t.Parallel()
	r := artRenderer()
	screen := ebiten.NewImage(256, 256)
	items := []creature.HeldItem{
		{Key: "weapon/rifle_basic", Stance: creature.StanceAimed, AimX: 9, AimY: 2},
		{Key: "weapon/rifle_basic", Stance: creature.StanceAimed, AimX: -3, AimY: 1.2},
		{Key: "weapon/spear", Stance: creature.StanceCarried},
		{Key: "item/wood_pile", Stance: creature.StanceLoad},
		{Push: 0.1}, // a punch: nothing held
	}
	var drawn []string
	r.lit.OnDraw = func(img *ebiten.Image, _ float32) { drawn = append(drawn, keyOf(r.art, img)) }
	for _, h := range items {
		for f := art.FaceSouth; f <= art.FaceWest; f++ {
			rig, ps := rigFor(r, f)
			n := len(drawn)
			for _, behind := range []bool{true, false} {
				r.drawHeld(screen, rig, h, 1, 1, 64, ps, behind)
			}
			if want := 1; h.Key != "" && len(drawn)-n != want {
				t.Fatalf("%v %+v: drawn %d times, want once (behind or in front)", f, h, len(drawn)-n)
			}
		}
	}
	r.lit.OnDraw = nil
	if len(drawn) == 0 || slices.Contains(drawn, staleHandKey) {
		t.Fatalf("items drawn, never a hand: %v", drawn)
	}
	rig, ps := rigFor(r, art.FaceEast)
	if _, ok := r.heldPoint(rig, creature.HeldItem{}, 1, 1, ps, "hold"); !ok {
		t.Fatal("bare hand point")
	}
	// a punch's reach pushes the bare hold point (the trail) along the facing
	rest, _ := r.heldPoint(rig, creature.HeldItem{}, 1, 1, ps, "hold")
	out, _ := r.heldPoint(rig, creature.HeldItem{Push: 0.14}, 1, 1, ps, "hold")
	if math.Abs(out.X-rest.X-0.14) > 1e-9 || out.Y != rest.Y {
		t.Fatalf("punch reach 0.14 east: %v -> %v", rest, out)
	}
	// an unknown sprite places nothing
	if _, ok := r.heldPlace(rig, creature.HeldItem{Key: "weapon/none"}, 1, 1, 64, ps); ok {
		t.Fatal("no sprite: no placement")
	}
}

// Facing north the carried weapon is drawn before the body (hidden
// behind it); facing south, east or west after it. No hand sprite is
// ever drawn.
func TestCarriedWeaponBehindFacingNorth(t *testing.T) {
	t.Parallel()
	for _, c := range []struct {
		f      art.Facing
		behind bool
	}{{art.FaceNorth, true}, {art.FaceSouth, false}, {art.FaceWest, false}, {art.FaceEast, false}} {
		r := New(&stubSim{w: 16, h: 16, tick: 100})
		r.art = figureArt()
		p := game.PawnView{ID: 1, X: 2, Y: 2, Weapon: "rifle", Drafted: true}
		var keys []string
		r.lit.OnDraw = func(img *ebiten.Image, _ float32) { keys = append(keys, keyOf(r.art, img)) }
		r.drawPawnFigure(ebiten.NewImage(512, 512), p, 2, 2, 64, creature.FigurePose{Face: c.f, Ps: creature.StandPose(), Held: creature.ReadyHeld(p)})
		body := slices.IndexFunc(keys, func(k string) bool { return strings.HasPrefix(k, "pawn/body_") })
		rifle := slices.Index(keys, "weapon/rifle_basic")
		if body < 0 || rifle < 0 || (rifle < body) != c.behind {
			t.Fatalf("%v: body %d rifle %d (%v)", c.f, body, rifle, keys)
		}
		if slices.Contains(keys, staleHandKey) {
			t.Fatalf("%v: a hand was drawn: %v", c.f, keys)
		}
	}
}
